using System;using System.IO;using System.Linq;using System.Text;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.SceneManagement;
namespace Staff.Shared.Editor {
[InitializeOnLoad] public static class SharedInspect {
static SharedInspect(){EditorApplication.update+=Poll;}
static void Poll(){const string d="Library/StaffShared";if(EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlaying||!File.Exists(d+"/inspect.request"))return;File.Delete(d+"/inspect.request");try{Run(d);}catch(Exception e){File.WriteAllText(d+"/error.txt",e.ToString());}}
static void Run(string d){var b=new StringBuilder();var prior=SceneManager.GetActiveScene();foreach(var path in new[]{"Assets/Scenes/SampleScene.unity","Assets/Scenes/STAFF_Subway_Reference.unity","Assets/Scenes/STAFF_City_Reference.unity"}){var s=SceneManager.GetSceneByPath(path);bool opened=!s.isLoaded;if(opened)s=EditorSceneManager.OpenScene(path,OpenSceneMode.Additive);b.AppendLine("SCENE "+path+" dirty="+s.isDirty);foreach(var g in s.GetRootGameObjects()){b.AppendLine("ROOT "+g.name+" "+g.transform.position+" "+g.transform.localScale);foreach(var c in g.GetComponentsInChildren<Component>(true)){if(!c)continue;if(c is Staff.Characters.AdventurePlayer||c is Staff.Characters.AdventureCamera||c is Staff.Subway.SubwayTimeOfDay||c is UnityEngine.Rendering.Volume||c is Staff.Subway.SubwayCar||c is Staff.Characters.CharacterSwitcher){b.AppendLine(c.GetType().Name+" "+PathOf(c.transform)+" "+c.transform.position+" scale="+c.transform.lossyScale);b.AppendLine(EditorJsonUtility.ToJson(c));}if(c is MonoBehaviour&&g.name=="Characters")b.AppendLine("CHAR "+PathOf(c.transform)+" "+c.GetType().Name);}}if(opened)EditorSceneManager.CloseScene(s,true);}SceneManager.SetActiveScene(prior);File.WriteAllText(d+"/inspection.txt",b.ToString());}
static string PathOf(Transform t)=>t.parent?PathOf(t.parent)+"/"+t.name:t.name;
}}
